from collections import deque
from typing import Any

Graph = dict[Any, list[Any]]

# BFS — shortest path (unweighted)
def bfs(graph: Graph, start: Any, target: Any) -> list | None:
    queue = deque([[start]])    # queue of paths, not just nodes
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        if node == target:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])
    return None

# BFS — level order tree traversal
def level_order(root) -> list[list]:
    if not root:
        return []
    result, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):   # process one level at a time
            node = queue.popleft()
            level.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(level)
    return result

# DFS — iterative (avoids recursion limit)
def dfs_iterative(graph: Graph, start: Any) -> list:
    visited, stack, order = set(), [start], []
    while stack:
        node = stack.pop()      # LIFO — stack not queue
        if node not in visited:
            visited.add(node)
            order.append(node)
            stack.extend(graph.get(node, []))
    return order

# DFS — recursive (cleaner for trees)
def dfs_recursive(graph: Graph, node: Any, visited: set = None) -> list:
    if visited is None:
        visited = set()
    visited.add(node)
    result = [node]
    for neighbor in graph.get(node, []):
        if neighbor not in visited:
            result.extend(dfs_recursive(graph, neighbor, visited))
    return result
